from griffe.extensions import Extension
from griffe.loader import load


class CheckedDocstringExtension(Extension):
    def on_create_docstring(self, docstring, **_kwargs):
        if docstring and docstring.value:
            docstring.value += " [checked]"
        return docstring


extensions = [CheckedDocstringExtension()]
package = load("mypkg", extensions=extensions)

for name, member in package.members.items():
    if hasattr(member, 'docstring') and member.docstring:
        print(f"{name}: {member.docstring.value[:50]}")
